// Input language code from previous node
const _lang = $input.first().json.lang || "es";
// Get client name safely from input
const rawName = $input.first().json.client_name;
const _wa_id = $input.first().json.wa_id;

// If the name exists and is a non-empty string → use it
// Otherwise → use an empty string ""
const clientName = (rawName && typeof rawName === "string") ? rawName : "";

// Text templates for each language
const messages = {
  en: `How are you, ${clientName}?
I'm Sophia, your virtual assistant from NewKeys Link.
I’m here to help you find the perfect car for you:
I can give you prices, mileage, features, compare models, review financing options, and also book your test-drive appointment.
Tell me, what kind of vehicle are you looking for?`,

  hi: `कैसे हैं आप, ${clientName}?
मैं सोफ़िया हूँ, आपकी वर्चुअल असिस्टेंट, NewKeys Link से।
मैं यहाँ आपकी मदद करने के लिए हूँ ताकि आप अपने लिए सही कार चुन सकें:
मैं आपको कीमतें, माइलेज, फीचर्स, मॉडल तुलना, फ़ाइनेंसिंग विकल्प बता सकती हूँ, और आपका टेस्ट-ड्राइव अपॉइंटमेंट भी बुक कर सकती हूँ।
बताइए, आप किस तरह की गाड़ी ढूंढ रहे हैं?`,

  ar: `كيف حالك ${clientName}؟
أنا صوفيا، مساعدتك الافتراضية من NewKeys Link.
أنا هنا لأساعدك في العثور على السيارة المثالية لك:
أستطيع أن أقدّم لك الأسعار، وعدد الكيلومترات، والمواصفات، ومقارنة الموديلات، وخيارات التمويل، وكذلك حجز موعد اختبار القيادة لك.
أخبرني، ما نوع السيارة التي تبحث عنها؟`,

  fr: `Comment allez-vous, ${clientName} ?
Je suis Sophia, votre assistante virtuelle chez NewKeys Link.
Je suis ici pour vous aider à trouver la voiture idéale pour vous :
je peux vous donner les prix, le kilométrage, les caractéristiques, comparer les modèles, vérifier les options de financement, et aussi réserver votre rendez-vous pour un essai routier.
Dites-moi, quel type de véhicule recherchez-vous ?`,

  // Fallback to Spanish if code doesn't match
  es: `Cómo estás ${clientName}.
Soy Sofía tu asistente virtual de NewKeys Link.
Estoy aquí para ayudarte a conseguir el carro ideal para ti:
puedo darte precios, kilometraje, características, comparar modelos, revisar opciones de financiamiento y también agendarte una cita para tu test drive.
Cuéntame qué tipo de vehículo estás buscando.`
};

// Determine the message to output
const _message = messages[_lang] || messages.es;

// Return as n8n output
return [{ message: _message, lang: _lang, wa_id: _wa_id }];
